const listPages = `-- name: ListPages :many


SELECT id, title, slug, body, body_format, status, seo_title, seo_desc, is_footer, created_at, updated_at
FROM page
WHERE ($1::text IS NULL OR title LIKE $1 OR slug LIKE $1)
  AND ($2::text IS NULL OR status = $2)
ORDER BY id DESC
LIMIT $4 OFFSET $3
`

type ListPagesParams struct {
	Pattern    pgtype.Text
	Status     pgtype.Text
	PageOffset int32
	PageLimit  int32
}

// 站点编排（S3-1 / S3-2 / A3-1 / A3-2，docs/specs/A3-1.md）：静态页、前台菜单、页面区块。
// LIKE 模式由领域层转义并加 %；pattern 为 NULL 表示不按文本搜。
// 「前台菜单」的查询名都带 Site 前缀，与 admin.sql 里「后台菜单」（admin_menu）的同名查询区分。
// ---------- 静态页（迁移 00024）----------
func (q *Queries) ListPages(ctx context.Context, arg ListPagesParams) ([]Page, error) {
	rows, err := q.db.Query(ctx, listPages,
		arg.Pattern,
		arg.Status,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Page{}
	for rows.Next() {
		var i Page
		if err := rows.Scan(
			&i.ID,
			&i.Title,
			&i.Slug,
			&i.Body,
			&i.BodyFormat,
			&i.Status,
			&i.SeoTitle,
			&i.SeoDesc,
			&i.IsFooter,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

